/**
 * @websublime/workspace-tools - Node.js bindings for workspace management
 *
 * This module provides the main entry point for the workspace-tools Node.js bindings.
 * It re-exports all functions and types from the native Rust bindings generated by napi-rs.
 *
 * ## What
 *
 * Re-exports all NAPI functions and TypeScript interfaces for:
 * - `getVersion()` - Get the version of the native bindings
 * - `status()` - Get workspace status information
 * - `init()` - Initialize workspace with changeset-based version management
 * - `changesetAdd()` - Add a new changeset to the workspace (Story 4.2)
 * - `changesetUpdate()` - Update an existing changeset (Story 4.3)
 * - `changesetList()` - List pending changesets with filtering (Story 4.4)
 * - `changesetShow()` - Show details of a specific changeset (Story 4.5)
 * - `changesetRemove()` - Remove a changeset from the workspace (Story 4.6)
 * - `changesetHistory()` - Query archived changeset history (Story 4.7)
 * - `changesetCheck()` - Check if a changeset exists for a branch (Story 4.8)
 * - `bumpPreview()` - Preview version bumps without applying changes (Story 5.2)
 * - `bumpApply()` - Apply version bumps with Git integration and prerelease support (Story 5.3)
 * - `bumpSnapshot()` - Generate snapshot versions for testing and CI (Story 5.4)
 * - `execute()` - Execute commands across workspace packages with timeout support (Story 6.3)
 * - `configShow()` - Show current workspace configuration (Story 7.2)
 *
 * Config types (Story 7.1):
 * - `ConfigShowParams`, `ConfigShowData`, `ConfigShowApiResponse`
 * - `ConfigValidateParams`, `ConfigValidateData`, `ConfigValidateApiResponse`
 * - `ConfigData`, `ConfigValidationIssue`
 * - Configuration section types: `ChangesetConfigInfo`, `VersionConfigInfo`, `DependencyConfigInfo`, etc.
 *
 * Bump types (Story 5.1):
 * - `BumpPreviewParams`, `BumpPreviewData`, `BumpPreviewApiResponse`
 * - `BumpApplyParams`, `BumpApplyData`, `BumpApplyApiResponse`
 * - `BumpSnapshotParams`, `BumpSnapshotData`, `BumpSnapshotApiResponse`
 * - `PackageVersionInfo`, `SnapshotVersionInfo`, `DependencyUpdateInfo`, `BumpSummaryInfo`
 *
 * Execute types (Story 6.2):
 * - `ExecuteParams`, `ExecuteData`, `ExecuteApiResponse`
 * - `PackageExecutionResult`, `ExecuteSummary`
 *
 * ## How
 *
 * The native bindings are compiled from Rust using napi-rs and exposed through
 * the `binding.js` and `binding.d.ts` files. This index module provides a clean
 * public API by selectively re-exporting the functions and types.
 *
 * ## Why
 *
 * Centralizing exports in an index file:
 * - Provides a stable public API surface
 * - Enables tree-shaking for bundlers
 * - Allows future refactoring without breaking changes
 * - Documents available exports in one place
 *
 * @packageDocumentation
 */

// Re-export all functions from bindings
import {
  bumpApply,
  bumpPreview,
  bumpSnapshot,
  changesetAdd,
  changesetCheck,
  changesetHistory,
  changesetList,
  changesetRemove,
  changesetShow,
  changesetUpdate,
  configShow,
  execute,
  getVersion,
  init,
  status,
} from './binding'

export {
  bumpApply,
  bumpPreview,
  bumpSnapshot,
  changesetAdd,
  changesetCheck,
  changesetHistory,
  changesetList,
  changesetRemove,
  changesetShow,
  changesetUpdate,
  configShow,
  execute,
  getVersion,
  init,
  status,
}

// Re-export all types from bindings
