  BumpSnapshotParams,

  // Response data
  BumpPreviewData,
  BumpApplyData,
  BumpSnapshotData,

  // API responses
  BumpPreviewApiResponse,
  BumpApplyApiResponse,
  BumpSnapshotApiResponse,

  // Supporting types
  PackageVersionInfo,
  SnapshotVersionInfo,
  DependencyUpdateInfo,
